#include <unistd.h>
#include <sys/inotify.h>
#include <errno.h>

int create_inotify_instance(int flags) {
    // Check if the provided flags are valid
    if ((flags & ~(IN_CLOEXEC | IN_NONBLOCK)) != 0) {
        errno = EINVAL;
        return -1;
    }

    // Create the inotify instance
    int fd = inotify_init1(flags);

    // Check if the file descriptor is valid
    if (fd < 0) {
        return -1;
    }

    return fd;
}
